// Shared shapes for the synthetic dataset. The data itself lives in
// syntheticData.ts, which is generated by scripts/generate-synthetic-data.ts.

export const WARDS = [
  'Cardiology',
  'Emergency',
  'General',
  'ICU',
  'Neurology',
  'Obstetrics',
  'Oncology',
  'Pulmonology',
] as const;

export type Ward = (typeof WARDS)[number];

export type RiskLevel = 'high' | 'medium' | 'low';

// Risk level is deliberately not stored here: the app derives it from the
// vitals with assessPatient() in src/lib/clinical.ts.
export interface Patient {
  id: string;
  name: string;
  age: number;
  ward: Ward;
  heartRate: number;
  systolic: number;
  diastolic: number;
  spo2: number;
  temperature: number;
  diagnosis: string;
  admittedAt: string;
}

export interface DeptWaitTime {
  department: Ward;
  avgWait: number;
  patientCount: number;
}

export type DiagnosticStatus = 'Critical' | 'Pending' | 'In Progress' | 'Completed';

export interface DiagnosticResult {
  id: string;
  test: string;
  patientId: string;
  status: DiagnosticStatus;
  requestedAt: string;
}

export interface DatasetMeta {
  seed: number;
  generatedAt: string;
}
